require_relative "test_helper"

# Calls every operation of the contract once. The mock answers with a sample that has the shape the
# contract declares (test/fixtures/responses.json); the test checks the request that was sent and that
# the decoded result carries the values that were served.
class SurfaceTest < TungoTestCase
  SAMPLES = Tungo::Internal::Util.parse_json(File.read(File.join(ROOT, "test", "fixtures", "responses.json"))).freeze

  def surface_client
    client(company_id: "co_1", workspace_id: "ws_1")
  end

  def sample(name, kind = "result")
    SAMPLES.fetch(name).fetch(kind)
  end

  def serve(data, status: 200)
    body = Tungo::Internal::Util.generate_json(data)
    server.respond { |_| { status: status, headers: { "content-type" => "application/json" }, body: body } }
  end

  def serve_event(data)
    name = data["type"].is_a?(String) ? data["type"] : "message"
    chunk = "event: #{name}\ndata: #{Tungo::Internal::Util.generate_json(data)}\n\n"
    server.respond { |_| MockServer.sse([chunk]) }
  end

  def assert_decoded(expected, model)
    assert_kind_of Tungo::Model, model
    refute_empty expected
    assert_equal expected, model.to_wire
  end

  def assert_events(expected, stream)
    events = stream.to_a

    assert_equal 1, events.size
    assert_decoded expected, events.first
  end

  def check(method, path, auth:, idempotent:, accept: "application/json")
    request = server.requests.last
    assert_equal method, request.verb
    assert_equal path, request.path
    assert_equal accept, request.headers["accept"]
    if auth
      assert_equal "tg_test_key", request.headers["x-api-key"]
    else
      assert_nil request.headers["x-api-key"]
      assert_nil request.headers["authorization"]
    end
    assert_equal idempotent, request.headers.key?("idempotency-key")
  end

